3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create-owner request that is missing or blank in any of firstName, lastName,
13	 * address, city or telephone, before {@link BuildOwner} runs. Runs first so an incomplete
14	 * body is a 400 naming the offending fields. Also normalizes the telephone into E.164 form
15	 * (see {@link OwnerTelephone}), rejecting otherwise with a 400; the normalized value is
16	 * stored on the body so it is persisted and returned.
17	 * When an {@code email} is present it must be a syntactically valid address and is stored
18	 * lower-cased (rejected with 400 otherwise); an absent email is allowed.
19	 * Publishes the validated body for later steps.
20	 */
21	public class ValidateOwnerFields {
22	
23	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
24	            throws MissingOwnerFieldsException, InvalidOwnerTelephoneException, InvalidOwnerEmailException,
25	            InvalidOwnerPostcodeException, FutureRegistrationDateException {
26	        // Normalize the address up front so the required-field check below rejects an address that
27	        // is blank after normalization, and the persisted/returned value is the normalized form.
28	        request.setAddress(OwnerAddress.normalize(request.getAddress()));
29	        List<String> missing = new ArrayList<>();
30	        checkField("firstName", request.getFirstName(), missing);
31	        checkField("lastName", request.getLastName(), missing);
32	        checkField("address", request.getAddress(), missing);
33	        checkField("city", request.getCity(), missing);
34	        checkField("telephone", request.getTelephone(), missing);
35	        if (!missing.isEmpty()) {
36	            throw new MissingOwnerFieldsException(missing);
37	        }
38	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
39	        OwnerEmail.normalize(request);
40	        OwnerPostcode.validate(request.getPostcode(), request.getCity());
41	        LocalDate registrationDate = request.getRegistrationDate();
42	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
43	            throw new FutureRegistrationDateException("registrationDate must not be later than the server date");
44	        }
45	        validated.set(request);
46	    }
47	
48	    private static void checkField(String name, String value, List<String> missing) {
49	        if (value == null || value.isBlank()) {
50	            missing.add(name);
51	        }
52	    }
53	}
